captures.usage:
var dark by rememberSaveable { mutableStateOf(false) }
BraceTheme(
    mode = if (dark) BraceColorMode.Dark else BraceColorMode.Light,
    density = BraceDensity.Comfortable,
) {
    BraceButton(if (dark) "Dark" else "Light", onClick = { dark = !dark })
}

var saves by rememberSaveable { mutableIntStateOf(0) }
BraceTheme(mode = BraceColorMode.Light) {
    BraceButton("Save ($saves)", onClick = { saves++ })
    BraceButton("Delete", onClick = {}, intent = BraceButtonIntent.Danger)
    BraceButton("Secondary", onClick = {}, variant = BraceButtonVariant.Outline)
}

BraceTheme(mode = BraceColorMode.Dark, contrast = BraceContrast.High) {
    BraceButton("Save", onClick = {})
    BraceButton("Delete", onClick = {}, intent = BraceButtonIntent.Danger)
}

var open by rememberSaveable { mutableStateOf(true) }
BraceTheme(mode = BraceColorMode.Dark) {
    BraceDialog(
        open = open,
        onDismissRequest = { open = false },
        title = "Edit project",
        actions = { BraceButton("Save", onClick = { open = false }) },
    ) { Text("Project details") }
}

val context = LocalContext.current
val pack by produceState<BraceBlueprintNextIconPack?>(null, context) {
    value = withContext(Dispatchers.IO) { BraceBlueprintNextIconPack.load(context) }
}
pack?.let { loaded ->
    BraceBlueprintNextIcon(
        loaded,
        BraceBlueprintNextIconNames.MagnifyingGlass,
        contentDescription = null,
        variant = BraceBlueprintNextIconVariant.Filled,
    )
}

BraceTheme(mode = BraceColorMode.Dark, contrast = BraceContrast.High) {
    BraceSpinner(label = "Loading small records", size = BraceSpinnerSize.Small)
    BraceSpinner(label = "Loading records", value = 0.3f)
    BraceSpinner(
        label = "Loading large reports",
        value = 0.3f,
        size = BraceSpinnerSize.Large,
        intent = BraceProgressIntent.Success,
    )
}

BraceTheme(mode = BraceColorMode.Light) {
    BraceSkeleton(label = "Loading report title")
    BraceSkeleton(width = 180.dp)
    BraceSkeleton(width = 120.dp)
}

var start by rememberSaveable { mutableStateOf<String?>(null) }
var end by rememberSaveable { mutableStateOf<String?>(null) }
BraceDateRangePicker(
    value = BraceDateRange(start?.let(LocalDate::parse), end?.let(LocalDate::parse)),
    onValueChange = { start = it.start?.toString(); end = it.end?.toString() },
    locale = Locale.US,
    shortcuts = listOf(BraceDateRangeShortcut("Sept 14–18",
        BraceDateRange(LocalDate.of(2026, 9, 14), LocalDate.of(2026, 9, 18)))),
)
